def main():
    print(f"Validating SMLE topics ({len(SMLE_TOPICS)})...")
    for i, t in enumerate(SMLE_TOPICS):
        title, subj, sys_name, focus, guide, url = t
        assert subj in TAXONOMY_SUBJECTS, f"Invalid subject '{subj}' in SMLE #{i+1}"
        assert sys_name in TAXONOMY_SYSTEMS, f"Invalid system '{sys_name}' in SMLE #{i+1}"
        assert len(title) > 20, f"Title too short in SMLE #{i+1}"
        assert url.startswith("https://"), f"Bad URL in SMLE #{i+1}"

    print(f"Validating UHS MBBS topics ({len(UHS_MBBS_TOPICS)})...")
    for i, t in enumerate(UHS_MBBS_TOPICS):
        title, subj, sys_name, focus, guide, url = t
        assert subj in TAXONOMY_SUBJECTS, f"Invalid subject '{subj}' in UHS MBBS #{i+1}"
        assert sys_name in TAXONOMY_SYSTEMS, f"Invalid system '{sys_name}' in UHS MBBS #{i+1}"
        assert len(title) > 20, f"Title too short in UHS MBBS #{i+1}"
        assert url.startswith("https://"), f"Bad URL in UHS MBBS #{i+1}"

    print("All 200 topics in Part A passed validation!")

    out_path = "scripts/mega72_topics_a.py"
    with open(out_path, "w", encoding="utf-8") as f:
        f.write("# Auto-generated Mega-Batch 72 Part A topics\n")
        f.write(f"SMLE_TOPICS = {repr(SMLE_TOPICS)}\n\n")
        f.write(f"UHS_MBBS_TOPICS = {repr(UHS_MBBS_TOPICS)}\n")
    print(f"Saved topics to {out_path}")

if __name__ == "__main__":
    main()
